CREATE TABLE app_users (id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE households (id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, created_by BIGINT NOT NULL REFERENCES app_users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE memberships (id BIGSERIAL PRIMARY KEY, household_id BIGINT NOT NULL REFERENCES households(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, role VARCHAR(20) NOT NULL, UNIQUE(household_id,user_id));
CREATE TABLE expenses (id BIGSERIAL PRIMARY KEY, household_id BIGINT NOT NULL REFERENCES households(id) ON DELETE CASCADE, paid_by BIGINT NOT NULL REFERENCES app_users(id), description VARCHAR(180) NOT NULL, category VARCHAR(40) NOT NULL, amount NUMERIC(12,2) NOT NULL CHECK (amount > 0), expense_date DATE NOT NULL, split_type VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE expense_shares (id BIGSERIAL PRIMARY KEY, expense_id BIGINT NOT NULL REFERENCES expenses(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES app_users(id), amount NUMERIC(12,2) NOT NULL CHECK (amount >= 0), UNIQUE(expense_id,user_id));
CREATE TABLE settlements (id BIGSERIAL PRIMARY KEY, household_id BIGINT NOT NULL REFERENCES households(id) ON DELETE CASCADE, payer_id BIGINT NOT NULL REFERENCES app_users(id), payee_id BIGINT NOT NULL REFERENCES app_users(id), amount NUMERIC(12,2) NOT NULL CHECK(amount > 0), status VARCHAR(20) NOT NULL, paid_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_expenses_household_date ON expenses(household_id,expense_date DESC);
CREATE INDEX idx_settlements_household_status ON settlements(household_id,status);
